($q$u-rosa$q$,$q$Rosa$q$,$q$Maipú$q$,72,array[$q$hacer videollamadas$q$]::text[],array[$q$pan amasado$q$]::text[],$q$clavel$q$,$q$$q$,1),
($q$u-equipo$q$,$q$Equipo SABERES$q$,$q$Santiago$q$,null,array[]::text[],array[]::text[],$q$$q$,$q$$q$,1),
