insert into public.guias (id,titulo,categoria,autor,autor_id,edad,comuna,materiales,pasos,ayudas,consejos,advertencias,claves,riesgo,estado,aprendieron,resumen_voz,creado_en) values
($q$g-videollamada$q$,$q$Cómo hacer una videollamada por WhatsApp$q$,$q$digital$q$,$q$Equipo SABERES$q$,$q$u-equipo$q$,null,$q$Santiago$q$,array[$q$Su celular con WhatsApp$q$,$q$Conexión a internet o wifi$q$]::text[],array[$q$Abra WhatsApp, el ícono verde con un teléfono blanco.$q$,$q$Toque el chat de la persona a la que quiere llamar.$q$,$q$Arriba a la derecha, toque el dibujo de la cámara de video.$q$,$q$Espere a que la otra persona conteste. Verá su cara en grande.$q$,$q$Sostenga el celular frente a su cara, a la altura de los ojos.$q$,$q$Para cortar, toque el botón rojo de abajo.$q$]::text[],array[$q$Busque en su celular un dibujo verde y redondo, con un teléfono blanco adentro. Tóquelo una vez con la yema del dedo.$q$,$q$En la lista de conversaciones, busque el nombre de la persona y toque encima de su nombre. Se abre la conversación.$q$,$q$Arriba de la pantalla, al lado del nombre, hay dos dibujos: un teléfono y una camarita. Toque la camarita: esa es la llamada con imagen.$q$,$q$El celular va a sonar como llamando. Puede que se demore un poquito; no toque nada mientras tanto.$q$,$q$Póngalo derechito, como si fuera un espejo, para que la otra persona le vea la cara y no el techo.$q$,$q$Abajo aparece un botón redondo y rojo con un teléfono. Tóquelo una vez y la llamada termina.$q$]::text[],array[$q$Si se escucha mal, acérquese al router del wifi o a una ventana.$q$]::text[],array[]::text[],array[$q$videollamada$q$,$q$video$q$,$q$llamada$q$,$q$llamar$q$,$q$whatsapp$q$,$q$camara$q$,$q$nietos$q$,$q$celular$q$]::text[],$q$bajo$q$,$q$publicada$q$,58,$q$Una guía para hablar con video por WhatsApp, en seis pasos.$q$,now() - interval $q$0 minutes$q$),
($q$g-estafa$q$,$q$Cómo saber si un mensaje es una estafa$q$,$q$digital$q$,$q$Equipo SABERES$q$,$q$u-equipo$q$,null,$q$Santiago$q$,array[$q$Su celular$q$,$q$El mensaje que le llegó$q$]::text[],array[$q$No toque ningún enlace del mensaje todavía.$q$,$q$Fíjese si le apuran: «urgente», «hoy», «su cuenta será bloqueada».$q$,$q$Fíjese si le piden claves, códigos o datos de su tarjeta. El banco nunca los pide por mensaje.$q$,$q$Mire quién lo envía: un número desconocido o un correo raro es mala señal.$q$,$q$Si dice ser un familiar con número nuevo, llámelo al número de siempre.$q$,$q$Ante la duda, borre el mensaje y llame usted a su banco, al número que sale en su tarjeta.$q$]::text[],array[$q$Un enlace es un texto azul o subrayado; a veces empieza con «http». Si lo toca, lo pueden llevar a una página falsa. Por ahora, solo mire.$q$,$q$Los estafadores quieren que usted se asuste y actúe rápido, sin pensar. Si el mensaje le apura, es una señal de alerta.$q$,$q$Ningún banco ni empresa seria le pide su clave por mensaje o por teléfono. Si se la piden, es estafa.$q$,$q$Si el mensaje viene de un número que usted no tiene guardado, o de un correo con letras raras, desconfíe.$q$,$q$Es un engaño común: «Hola mamá, cambié de número». Llame a su familiar al número que usted ya conoce y pregúntele.$q$,$q$Puede borrar el mensaje sin miedo. Para hablar con su banco, use el número que está detrás de su tarjeta, nunca el del mensaje.$q$]::text[],array[$q$Si alguien le apura, desconfíe. Lo que es verdad puede esperar una llamada.$q$]::text[],array[$q$Nunca entregue la clave o el código que le llega por SMS, ni a alguien que diga ser del banco.$q$]::text[],array[$q$estafa$q$,$q$estafas$q$,$q$mensaje$q$,$q$fraude$q$,$q$engano$q$,$q$banco$q$,$q$cuento$q$,$q$phishing$q$,$q$sms$q$,$q$seguridad$q$]::text[],$q$bajo$q$,$q$publicada$q$,41,$q$Seis señales para reconocer un mensaje falso.$q$,now() - interval $q$1 minutes$q$),
($q$g-pan-amasado$q$,$q$Pan amasado$q$,$q$cocina$q$,$q$Señora Rosa$q$,$q$u-rosa$q$,72,$q$Maipú$q$,array[$q$1 kilo de harina$q$,$q$1 cucharada de sal$q$,$q$10 gramos de levadura seca$q$,$q$125 gramos de manteca$q$,$q$2 tazas de agua tibia$q$,$q$El horno prendido a 200 grados$q$]::text[],array[$q$Disuelva la levadura en media taza de agua tibia con una pizca de azúcar y déjela reposar 10 minutos.$q$,$q$En un bol grande, mezcle la harina con la sal y haga un hoyo al medio.$q$,$q$Derrita la manteca, que quede tibia, y échela al hoyo junto con la levadura.$q$,$q$Agregue el resto del agua de a poco, mientras mezcla con la mano.$q$,$q$Amase unos 10 minutos, hasta que la masa esté suave y no se pegue.$q$,$q$Haga bolitas, aplástelas un poco, píncheles con un tenedor y déjelas reposar tapadas 20 minutos.$q$,$q$Hornee de 20 a 25 minutos, hasta que estén doraditas.$q$]::text[],array[$q$La levadura es lo que hace que el pan se infle. Póngala en una taza con agua tibia, como para bañar a una guagua, y una pizca de azúcar. Si a los 10 minutos hace espuma, está viva y lista.$q$,$q$Ponga la harina en un bol grande, eche la sal y con la mano haga un hueco al centro, como un volcán.$q$,$q$Caliente la manteca en una olla chica hasta que se derrita, y espere que se entibie para no matar la levadura. Échela al hueco junto con la levadura.$q$,$q$Eche el agua de a chorritos y vaya juntando la harina desde los bordes hacia el centro, hasta que se forme una masa.$q$,$q$Amasar es empujar la masa con la palma de la mano, doblarla y volver a empujar. Cuando ya no se le pegue en los dedos, está lista.$q$,$q$Saque pedazos del porte de un huevo, hágalos bolita, aplástelos con la mano y píncheles tres veces con un tenedor. Tápelos con un paño y déjelos descansar.$q$,$q$Ponga los panes en una lata con un poco de harina y métalos al horno caliente. Están listos cuando se ven dorados por encima.$q$]::text[],array[$q$El agua tiene que estar tibia, como para bañar a una guagua. Si está caliente, mata la levadura.$q$,$q$Tape la masa con un paño limpio y déjela cerca de la cocina, que ahí sube mejor.$q$]::text[],array[$q$Use un paño o un guante para sacar la lata del horno.$q$]::text[],array[$q$pan$q$,$q$amasado$q$,$q$hallulla$q$,$q$masa$q$,$q$hornear$q$,$q$harina$q$,$q$once$q$]::text[],$q$bajo$q$,$q$publicada$q$,34,$q$La receta de pan amasado de la Señora Rosa, en siete pasos.$q$,now() - interval $q$2 minutes$q$),
($q$g-tomates$q$,$q$Plantar tomates en macetero$q$,$q$huerto$q$,$q$Don Luis$q$,$q$u-luis$q$,68,$q$La Florida$q$,array[$q$Un macetero de al menos 30 centímetros de hondo, con hoyos abajo$q$,$q$Tierra de hoja$q$,$q$Un almácigo de tomate$q$,$q$Un palo o caña de un metro$q$,$q$Piedritas$q$,$q$Agua$q$]::text[],array[$q$Ponga piedritas en el fondo del macetero para que el agua escurra.$q$,$q$Llene el macetero con tierra hasta cuatro dedos antes del borde.$q$,$q$Haga un hoyo al medio, del porte del vasito del almácigo.$q$,$q$Ponga la plantita y entiérrela un poco más honda de lo que venía.$q$,$q$Clave el palo al lado y amarre el tallo suavecito con una lana.$q$,$q$Riegue hasta que salga agua por abajo y deje el macetero al sol.$q$]::text[],array[$q$En el fondo del macetero ponga un puñado de piedritas o pedazos de ladrillo. Así el agua no se queda estancada y la raíz no se pudre.$q$,$q$Eche tierra hasta que quede un espacio como de cuatro dedos juntos entre la tierra y el borde. Ese espacio sirve para regar.$q$,$q$Con la mano o una cuchara, haga un hoyo en el centro, más o menos del tamaño del vasito donde viene la plantita.$q$,$q$Saque la plantita del vasito con cuidado, sin tirarla del tallo. Póngala en el hoyo y tape con tierra hasta un poco más arriba de donde estaba.$q$,$q$El palo sirve para que la planta se apoye cuando crezca. Amárrela con una lana floja, como una pulsera suelta, para no apretar el tallo.$q$,$q$Riegue despacito hasta que vea salir agua por los hoyos de abajo. Deje el macetero donde le dé sol por lo menos 6 horas al día.$q$]::text[],array[$q$Riegue en la mañana temprano o al atardecer, nunca a pleno sol.$q$,$q$Sáquele los brotecitos que salen entre el tallo y las hojas; así da más tomates.$q$]::text[],array[]::text[],array[$q$tomate$q$,$q$tomates$q$,$q$plantar$q$,$q$macetero$q$,$q$huerto$q$,$q$sembrar$q$,$q$planta$q$,$q$jardin$q$,$q$cultivar$q$]::text[],$q$bajo$q$,$q$publicada$q$,21,$q$Cómo plantar tomates en un macetero, en seis pasos.$q$,now() - interval $q$3 minutes$q$),
($q$g-boton$q$,$q$Coser un botón que se salió$q$,$q$hogar$q$,$q$Señora Carmen$q$,$q$u-carmen$q$,75,$q$Ñuñoa$q$,array[$q$El botón$q$,$q$Una aguja$q$,$q$Hilo del mismo color, unos 50 centímetros$q$,$q$Tijeras$q$,$q$Un alfiler o un fósforo$q$]::text[],array[$q$Enhebre la aguja, junte las dos puntas del hilo y hágales un nudo.$q$,$q$Busque las marcas del botón antiguo en la tela, para ponerlo en el mismo lugar.$q$,$q$Entre la aguja por el revés de la tela y sáquela por un hoyito del botón.$q$,$q$Ponga un alfiler encima del botón y cosa pasando por arriba del alfiler, unas 6 veces.$q$,$q$Saque el alfiler, saque la aguja entre el botón y la tela, y enrolle el hilo 3 veces debajo del botón.$q$,$q$Pase la aguja al revés, haga dos puntaditas para rematar y corte el hilo.$q$]::text[],array[$q$Pase la punta del hilo por el hoyito de la aguja. Si le cuesta, moje la punta del hilo. Luego junte las dos puntas y haga un nudo.$q$,$q$Mire la tela donde estaba el botón: van a quedar hoyitos o pedacitos de hilo. Ahí va el botón, para que calce con el ojal.$q$,$q$El revés es el lado de adentro de la ropa. Entre la aguja desde adentro, para que el nudo quede escondido, y sáquela por uno de los hoyitos del botón.$q$,$q$El alfiler encima del botón sirve para dejarlo un poquito suelto. Pase la aguja por un hoyito, por encima del alfiler, y baje por el otro hoyito. Repítalo unas seis veces.$q$,$q$Saque el alfiler. Ahora el botón queda un poco separado de la tela: pase la aguja por ese espacio y enrolle el hilo tres vueltas alrededor, como un cuellito.$q$,$q$Pase la aguja al lado de adentro, haga dos puntaditas chiquitas en el mismo lugar para asegurar, y corte el hilo que sobra.$q$]::text[],array[$q$El alfiler deja el botón un poquito suelto; así abrocha fácil y no se vuelve a salir.$q$]::text[],array[]::text[],array[$q$boton$q$,$q$botones$q$,$q$coser$q$,$q$costura$q$,$q$aguja$q$,$q$hilo$q$,$q$ropa$q$,$q$camisa$q$]::text[],$q$bajo$q$,$q$publicada$q$,12,$q$Cómo coser un botón para que no se vuelva a salir, en seis pasos.$q$,now() - interval $q$4 minutes$q$);
